import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;
  const root = new Group();

  // Store references for cleanup
  const cleanupRefs = {
    hoverTL: null,
    clickTLs: [],
    gltf: null,
  };

  // Load GLB mesh
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    cleanupRefs.gltf = gltf;
    const meshGroup = gltf.scene || gltf;
    root.add(meshGroup);
  });

  // Hover lift (rise-in) animation
  function startHover() {
    if (cleanupRefs.hoverTL) cleanupRefs.hoverTL.kill();
    cleanupRefs.hoverTL = gsap.to(root.position, {
      y: 0.15,
      duration: 0.25,
      ease: 'power3.out',
    });
  }

  function endHover() {
    if (cleanupRefs.hoverTL) cleanupRefs.hoverTL.kill();
    cleanupRefs.hoverTL = gsap.to(root.position, {
      y: 0,
      duration: 0.25,
      ease: 'power3.out',
    });
  }

  // Click press-down + emit
  function onClick() {
    ctx.emit('hub-home.select', {});
    const tl = gsap.timeline();
    tl.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    })
      .to(root.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'power2.out',
      });
    cleanupRefs.clickTLs.push(tl);
  }

  // Attach interaction handlers
  root.userData.handlers = {
    hoverEnter: startHover,
    hoverLeave: endHover,
    click: onClick,
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    if (cleanupRefs.hoverTL) cleanupRefs.hoverTL.kill();
    cleanupRefs.clickTLs.forEach((tl) => tl.kill());

    if (cleanupRefs.gltf && cleanupRefs.gltf.scene) {
      cleanupRefs.gltf.scene.traverse((obj) => {
        if (obj.isMesh) {
          obj.geometry?.dispose?.();
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose?.());
          } else {
            obj.material?.dispose?.();
          }
        }
      });
    }
  };

  // Apply any cinematic primitives (none in this spec, but loop for safety)
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      const prim = ctx.primitives[primitive.name];
      if (prim) {
        const result = prim(root, primitive.params);
        // Store cleanup for primitive
        if (result && result.cleanup) {
          const prevCleanup = root.userData.cleanup;
          root.userData.cleanup = () => {
            result.cleanup();
            if (prevCleanup) prevCleanup();
          };
        }
      }
    });
  }

  return root;
}
